using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class GabrieleDAnnunzio
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ardisco non ordisco.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Arma la prora e salpa verso il Mondo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Credo nell'esperienza di un fato che ci genera e ci costringe a sporcare la faccia del mondo per vedere come ce la caveremo. Per difendermi ho imparato a maneggiare il fango. In fondo solo con il fango una mano sapiente può costruire qualche cosa che resista al fuoco. Anche se i più lo maneggiano non per costruire, ma per insozzare e per distruggere.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Compagni, non è più tempo di parlare ma di fare; non è più tempo di concioni ma di azioni, e di azioni romane. Se considerato è come crimine l'incitare alla violenza i cittadini, io mi vanterò di questo crimine, io lo prenderò sopra me solo. Se invece di allarmi io potessi armi gettare ai risoluti, non esiterei; né mi parrebbe di averne rimordimento. Ogni eccesso della forza è lecito, se vale a impedire che la Patria si perda. Voi dovete impedire che un pugno di ruffiani e di frodatori riesca a imbrattare e a perdere l'Italia. Tutte le azioni necessarie assolve la legge di Roma.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ho vinto. La convalescenza comincia. Vive, vivrà. In quella sera d'afa e di lampi muti, il commiato era in fondo agli occhi dei medici. Essi esitavano di guardarmi. Uno, il più illustre, uscendo dalla stanza dove l'odore della dissoluzione si faceva intollerabile, mormorò: \"soltanto il miracolo potrebbe...\". Credo nel miracolo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il mondo è la rappresentazione della sensibilità e del pensiero di pochi uomini superiori.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il piacere è il più certo mezzo di conoscimento offertoci dalla Natura e [...] colui il quale molto ha sofferto è men sapiente di colui il quale ha molto gioito.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il socialismo in Italia è un'assurdità. Fra quella gente e me esiste una barriera insormontabile. Sono e rimango individualista ad oltranza. Un individualista feroce. Mi piacque di entrare un istante nella fossa dei leoni; ma vi fui spinto dal disgusto per gli altri partiti.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io ho quel che ho donato perché nella vita ho sempre amato.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io intendo rimanere al Polo: voi mi lascerete lassù. Un uomo come me non può morire in un cataletto. Egli deve scomparire nel mistero di una leggenda. lo diverrò l'asse della Terra.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io sono un animale di lusso; e il superfluo m'è necessario come il respiro.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "L'automobile è femmina.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "L'uomo è, sopra tutto, un animale accomodativo. Non c'è turpitudine o dolore a cui non s'adatti.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Lo stile è potenza isolatrice.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Me ne frego'' è scritto nel centro del gagliardetto azzurro che l'altra notte consegnai ai serventi delle mie mitragliatrici blindate, tra i pinastri selvaggi della collina, al lume delle torce e delle stelle, mentre la piccola schiera dei volontari dalmati cantava il vecchio canto del Quarantotto, grande come il tuono dell'organo nelle navate di Sebenico o di Spalato. Il motto è crudo. Ma a Fiume la mia gente non ha paura di nulla, neppure delle parole.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Non ritroverete mai la vostra donna -amata, amante- così com'era quando da lei vi separaste.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Non temere! Accogli l'ignoto e l'impreveduto e quanto altro ti recherà l'evento; abolisci ogni divieto; procedi sicuro e libero. Non avere omai sollecitudine se non di vivere. Il tuo fato non potrà compiersi se non nella profusione della vita.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "O beati quelli che più hanno, perché più potranno dare, più potranno ardere.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Osare l'inosabile.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Perché siete fuggita? Nike, non volete essere il mio grande amore? Il solo coraggio vi manca perché non avete mai sentito tutto il mondo dentro di voi, non avete mai appartenuto a voi stessa. Così la vostra fanciullezza se ne è andata come una inutile folata di petali in un soffio di malinconia: e la giovinezza vi ha trovata col forziere intatto. Esiste nella vostra anima tutta un'immensa zona di sensibilità inesplorata ed ignota a voi stessa. Chi vi sente'' la intuisce e talvolta riesce persino a percepirla come un ritmo istintivamente musicale emergente da una cacofonia. Io ho l'orecchio fine, Nike, miracolo biondo: ed ho tanta sete di lasciar cullare la mia anima da quel ritmo. Vi amo. Vi amo. E di questo amore e in questo amore sono folle e smarrito.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Possedeva una scienza mirabile (ch'era forse un raro senso) di tutte le minime particolarità di tempo e di grado le quali concorrono a infinitamente variare sul rame l'efficacia dell'acquaforte... Quel natio senso quasi infallibile l'avvertiva del momento giusto, dell'attimo puntuale, in cui la corrosione giungeva a dare tal preciso valor d'ombra che nell'intenzion dell'artefice doveva avere la stampa.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ricordati di osare sempre.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Si vive per anni accanto a un uomo|essere umano, senza vederlo. Un giorno, ecco che uno alza gli occhi e lo vede. In un attimo, non si sa perché, non si sa come, qualcosa si rompe: una diga fra due acque. E due sorti si mescolano, si confondono e precipitano.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Tutto, infatti, è qui da me creato o trasfigurato. Tutto qui mostra le impronte del mio stile, nel senso che io voglio dare allo stile.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Una bella donna è mille volte più attraente quando esce dalle braccia di Morfeo che dopo un'accurata toilette.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Giova ciò solo che non muore, e solo per noi non muore, ciò che muor con noi.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Le mie passioni sono le mie virtù.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Prima, circa una trentina d'anni fa, tutte le donne erano brune, d'un bruno profondo e fatale, 'mer d'ébène noir ocèan, pavillon de ténèbres tendues', come cantava Carlo Baudelaire. Ora, invece, una donna che non è bionda non è una donna.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "È insipida la gioia che non abbia in sé una promessa di dolore.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il viso dell'amore è osceno come quello di un pagliaccio vinoso.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "La Chiesa di San Luigi de' Francesi è l'ovile consueto dove tutte le pecorelle di Roma aristocratica e delle colonie straniere accorrono tre volte la settimana per purificarsi nella tiepida e opaca eloquenza del padre Le Méhauté. In verità, di tipiedo nella chiesa di San Luigi non c'è che l'eloquenza del predicatore. Spira per le navate un'aura così rigida e la luce anche, piovente dall'alto, è così grigia ch'io non so come le peccatrici possano resistere un'ora nella quasi immobilità del pregare e dell'ascoltare.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "La piazza di Spagna, la più bella piazza del mondo, una piazza in cui pare sia raccolto tutto il fascino della mollezza quirite, una piazza fatta per l'ozio, per la voluttà dell'ozio e per i convegni d'amore, per la guarigione dei convalescenti e per lo struggimento delli innamorati, per tutti quelli che amano i fiori, le donne, i 'sandwiches', il thé, i tappeti orientali, la piazza di Spagna è un luminoso tepidario cattolico, protetto dalla Madonna 'fons amoris'!", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il solito gran concerto annuale di Augusto Rotoli aveva l'inesplicabile fascino che hanno su gli uomini e su le donne le consuetudini stupide, inutili e noiose. Ognuno andava e restava fino alla fine, così, senza sapere perché, con un'abnegazione inconsapevole, vinto da un affievolimento infinito, sentendo la sua volontà scomparire.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il giudizio popolare, in verità, non è molto favorevole all'architettura esterna del Teatro Drammatico Nazionale. Quella facciata ha un'aria di pretensione e di volgarità che si accorda mirabilmente con il vergognoso barocchismo dei quartieri alti; e sta tra la vecchia e la nuova Roma come un simbolo, come un assai feroce simbolo della tircheria e della piccineria moderna...", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ignudo le membra agilissime a'l sole ed a l'acqua.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "A 'l mare, a 'l mare, Lalla, a 'l mio libero tristo fragrante verde Adriatico.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Chiedon l'esametro lungo salente i fantasmi che su dal core baldi mi fioriscono, e l'onda armonica al breve pentametro spira in un pispiglio languido di dattili.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ma ancora ancor mi tentan le spire volubili tue, o alata strofe, coppia di serpentelli alati.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Quando un grande poeta volge la fronte verso l'Eternità, la mano pia che gli chiude gli occhi sembra suggellare sotto le esangui palpebre la più luminosa parte della bellezza terrena.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Chi potrà dire quando e dove sien nate le figure che a un tratto sorgono dalla parte spessa e opaca di noi e ci apariscono turbandoci? Gli eventi più ricchi accaddono in noi assai prima che l'anima se n'accorga. E, quando noi cominciamo ad aprire gli occhi sul visibile, già eravamo da tempo aderenti all'invisibile.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "L'anima della terra è notturna, ma la luce del sole la nasconde più che non la nasconda la tenebra.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Un fiotto di sanità caldo la riempiva; certe sùbite gioie di vivere le muovevano il sangue, le mettevano nel petto quasi dei battimenti d'ale, le mettevano de' canti nella bocca.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Solo il sambuco odorava dalle ampie antele candide fresco e mite, là entro. Le farfalle passavano fuggevoli; gruppi di chiocciole andavano qua e là strisciando tra le piante succose, lasciando le righe lucenti.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Una stanchezza immensa le invadeva tutto l'essere; e in quella prostrazione ella conservava ancora la sensazione del ribrezzo che l'aveva scossa; mentre, dinanzi alla felicità crescente del mattino primaverile, un rimpianto amaro, il rimpianto di qualche cosa d'irrimediabile, singhiozzava in lei. Tutto era finito; ella era vecchia, ella doveva dunque morire.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io pensava in un pomeriggio recente — tornando dai Giardini per quella tiepida riva degli Schiavoni che all'anima dei poeti vaganti potè sembrar talvolta non so qual magico ponte d'oro prolungato su un mare di luce e di silenzio verso un sogno di Bellezza infinito — io pensava, anzi assisteva nel mio pensiero come a un intimo spettacolo, alla nuziale alleanza dell'Autunno e di Venezia sotto i cieli. Era per ovunque diffuso uno spirito di vita, fatto d'aspettazione appassionata e di contenuto ardore; che mi stupiva per la sua veemenza ma che pur non mi sembrava nuovo poichè io l'aveva già trovato raccolto in qualche zona d'ombra, sotto l'immobilità quasi mortale dell'Estate, e l'aveva anche sentito fra lo strano odor febrile dell'acqua vibrar quivi a quando a quando come un polso misterioso. — Così, veramente, questa pura Città d'arte aspira a una suprema condizione di bellezza, che è per lei un annuale ritorno come per la selva il dar fiori. Ella tende a rivelar sé medesima in una piena armonia quasi che sempre ella porti in sé possente e consapevole quella volontà di perfezione da cui nacque e si formò nei secoli come una creatura divina. Sotto l'immobile fuoco dei cieli estivi, ella pareva senza palpito e senza respiro, morta nelle sue verdi acque; ma non m'ingannò il mio sentimento quando io la indovinai travagliata in segreto da uno spirito di vita bastevole a rinnovare il più alto degli antichi prodigi. Questo io pensava, assistendo allo spettacolo incomparabile che per un dono di amore e di poesia io poteva contemplare con occhi attentissimi la cui vista mi si mutava in visione profonda e continua... Ma con qual virtù potrò io mai comunicare a chi m'ascolta questa mia visione di bellezza e di gioia? Non v'è aurora e non v'è tramonto che valgano una simile ora di luce su le pietre e su le acque. Né subito apparire di donna amata in foresta di primavera è inebriante così come quella impreveduta rivelazione diurna della Città eroica e voluttuosa che portò e soffocò nelle sue braccia di marmo il più ricco sogno dell'anima latina.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Era come una landa stigia, come una visione dell'Ade: un paese di ombre, di vapori e di acque. Tutte le cose vaporavano e vanivano come spiriti. La luna incantava e attirava la pianura com'ella incanta e attira il mare: beveva dall'orizzonte la grande umidità terrestre, con una gola insaziabile e silenziosa. Ovunque brillavano pozze solinghe; si vedevano piccoli canali argentei riscintillare in una lontananza indefinita tra file di salci reclinati. La terra pareva perdere a ora a ora la sua saldezza e liquefarsi; il cielo poteva mirarvi la sua malinconia riflessa da innumerevoli specchi quieti. E di qua, di là, per la scolorata riviera, come i Mani d'una gente scomparsa le statue passavano passavano.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Pensò la lentezza del dormiveglia, l'indugio del sopore verso l'alba, quando la volontà velata guida leggermente il sogno felice.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Bisogna fare'' la propria vita, come si fa un'opera d'arte. Bisogna che la vita d'un uomo d'intelletto sia opera di lui. La superiorità vera è tutta qui.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Bisogna conservare ad ogni costo intiera la libertà, fin nell'ebrezza. La regola dell'uomo d'intelletto, eccola: ― Habere, non haberi.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il rimpianto è il vano pascolo d'uno spirito disoccupato. Bisogna sopra tutto evitare il rimpianto occupando sempre lo spirito con nuove sensazioni e con nuove imaginazioni.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il sofisma [...] è in fondo ad ogni piacere e ad ogni dolore umano. Acuire e moltiplicare i sofismi equivale dunque ad acuire e moltiplicare il proprio piacere o il proprio dolore. Forse, la scienza della vita sta nell'oscurare la verità. La parola è una cosa profonda, in cui per l'uomo d'intelletto son nascoste inesauribili ricchezze. I Greci, artefici della parola, sono in fatti i più squisiti goditori dell'antichità. I sofismi fioriscono in maggior numero al secolo di Pericle, al secolo gaudioso.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Aveva la voce così insinuante che quasi dava la sensazione d'una carezza carnale; e aveva quello sguardo involontariamente amoroso e voluttuoso che turba tutti li uomini e ne accende d'improvviso la brama.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Ci sono certi sguardi di donna che l'uomo amante non iscambierebbe con l'intero possesso del corpo di lei. Chi non ha veduto accendersi in un occhio limpido il fulgore della prima tenerezza non sa la più alta delle felicità umane. Dopo, nessun altro attimo di gioia eguaglierà quell'attimo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Da certi suoni della voce e del riso, da certi gesti, da certe attitudini, da certi sguardi ella esalava, forse involontariamente, un fascino troppo afrodisiaco.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Certo, quanto più la cosa da un uom posseduta suscita nelli altri l'invidia e la brama, tanto più l'uomo ne gode e n'è superbo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Quell'aria aspettava il 'suo' respiro; quei tappeti chiedevano d'esser premuti dal 'suo' piede; quei cuscini volevano l'impronta del 'suo' corpo.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "La convalescenza è una purificazione e un rinascimento. Non mai il senso della vita è soave come dopo l'angoscia del male; e non mai l'anima umana più inclina alla bontà e alla fede come dopo aver guardato negli abissi della morte. Comprende l'uomo, nel guarire, che il pensiero, il desiderio, la volontà, la conscienza della vita non sono la vita. Qualche cosa è in lui più vigile del pensiero, più continua del desiderio, più potente della volontà, più profonda anche della conscienza; ed è la sostanza, la natura dell'essere suo. Comprende egli che la sua vita reale è quella, dirò così, non vissuta da lui; è il complesso delle sensazioni involontarie, spontanee, incoscienti, istintive; è l'attività armoniosa e misteriosa della vegetazione animale; è l'impercettibile sviluppo di tutte le metamorfosi e di tutte le rinnovellazioni. Quella vita appunto in lui compie i miracoli della convalescenza: richiude le piaghe, ripara le perdite, riallaccia le trame infrante, rammenda i tessuti lacerati, ristaura i congegni degli organi, rinfonde nelle vene la ricchezza del sangue, riannoda su gli occhi la benda dell'amore, rintreccia d'intorno al capo la corona de' sogni, riaccende nel cuore la fiamma della speranza, riapre le ali alle chimere della fantasia.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Per la prima volta, infatti, il giovine conobbe tutta l'armoniosa poesia notturna de' cieli estivi. Erano le ultime notti d'agosto, senza luna. Innumerevoli, nella profonda conca, palpitava la vita ardente delle constellazioni. Le Orse, il Cigno, Ercole, Boote, Cassiopea riscintillavano con un palpito così rapido e così forte che quasi parevano essersi appressati alla terra, essere entrati nell'atmosfera terrena. La Via Lattea svolgevasi come un regal fiume aereo, come un adunamento di riviere paradisiache, come una immensa correntìa silenziosa che traesse nel suo 'miro gurge' una polvere di minerali siderei, passando sopra un àlveo di cristallo, tra falangi di fiori. Ad intervalli, meteore lucide rigavano l'aria immobile, con la discesa lievissima e tacita d'una goccia d'acqua su una lastra di diamante. Il respiro del mare, lento e solenne, bastava solo a misurare la tranquillità della notte, senza turbarla; e le pause eran più dolci del suono.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Il verso è tutto.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "'Schifanoja' in Ferrara (oh gloria d'Este!), ove il Cossa emulò Cosimo Tura in trionfi d'iddii su per le mura, non vide mai tanto gioconde feste.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Da che vi ho conosciuta, ho molto sognato per voi, di giorno e di notte, ma senza una speranza e senza un fine. Io so che voi non mi amate e che non potete amarmi. E pure, credetemi, io rinunzierei a tutte le promesse della vita per vivere in una piccola parte del vostro cuore...", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Erano i primissimi tempi della felicità: egli usciva caldo di baci, pieno della recente gioja; le campane della Trinità de' Monti, di Sant'Isidoro, de' Cappuccini sonavano l'Angelus'' nel crepuscolo, confusamente, come se fossero assai più lontane; all'angolo della via rosseggiavano i fuochi intorno le caldaje dell'asfalto; un gruppo di capre stava lungo il muro biancastro, sotto una casa addormentata; i gridi fiochi degli acquavitari si perdevano nella nebbia....", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io vi amo come nessuna parola umana potrà mai esprimere. Ho bisogno di voi. Voi soltanto siete 'vera'; voi siete la Verità che il mio spirito cerca. Il resto è vano; il resto è nulla.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "Io sono camaleontico, chimerico, incoerente, inconsistente. Qualunque mio sforzo verso l'unità riuscirà sempre vano. Bisogna omai ch'io mi rassegni. La mia legge è in una parola: NUNC. Sia fatta la volontà della legge.", Author = "Gabriele D'Annunzio" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Gabriele_D'Annunzio", Text = "[...] e credere in te 'soltanto', giurare in te 'soltanto', riporre in te 'soltanto' la mia fede, la mia forza, il mio orgoglio, tutto il mio mondo, tutto quel che sogno, e tutto quel che spero....", Author = "Gabriele D'Annunzio" },
        };
    }
}